const slides = [
  { title: 'Presentación de la Materia', eyebrow: '01 · Apertura', body: `<p class="lede">INGENIERÍA DE SOFTWARE I</p><p>Prof. Lic. Guillermo Jacobo González Rodas Mst. PMP</p>`, visual: `<div class="visual-title">Ingeniería de Software I</div><div class="quote">Una disciplina para construir software eficiente, seguro y mantenible.</div>`, note: '<strong>Desarrollo:</strong> Presentar Ingeniería de Software I como una asignatura que estudia cómo producir y sostener software, no solamente cómo programarlo. Usar esta apertura para ubicar la unidad y el contexto de trabajo del curso.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): tomemos el curso como el mapa para construir un sistema de cambio de divisas, desde entender el problema hasta mantenerlo. Segundo contexto industrial: en un sistema de turnos hospitalarios, también necesitaremos organizar decisiones, roles y controles antes de escribir código.<br><br><strong>Reflexión docente:</strong> La profesión exige ampliar la mirada: una solución técnicamente interesante puede fallar si no responde al contexto de uso.<br><br><strong>Pregunta desafío:</strong> ¿qué diferencia esperan encontrar entre programar y ejercer Ingeniería de Software?<br><br><strong>Respuestas posibles:</strong> 1. Programar implementa una solución; la Ingeniería de Software organiza todo su ciclo de vida. 2. La Ingeniería de Software incorpora requisitos, calidad, coordinación, riesgos y mantenimiento. 3. Una persona puede programar correctamente y aun así no resolver el problema completo del sistema.<br><br><strong>Advertencia:</strong> esta apertura contextualiza; todavía no define conceptos técnicos.' },
  { title: 'Sobre el Docente', eyebrow: '02 · Contexto', body: `<div style="display: flex; gap: 2rem; align-items: flex-start;"><img src="assets/foto-docente.png" alt="Foto del docente" style="width: 180px; height: 180px; object-fit: cover; border-radius: 50%; border: 3px solid var(--fpuna-blue); flex-shrink: 0;"><div><p><strong>Prof. Lic. Guillermo Jacobo González Rodas Mst. PMP</strong></p><p>Paraguayo, Profesional, egresado de la carrera de Licenciatura en Análisis de Sistemas Informáticos de la Facultad Politécnica de la Universidad Nacional de Asunción. Ha realizado un Máster en Ingeniería del Software por la Universidad Politécnica de Catalunya, Barcelona - España. Tiene la certificación de PMP (Project Management Professional) del PMI (Project Management Institute).</p><p>Es Consultor de TICs, especializado en Gestión de Proyectos e Implementación de sistemas de información empresariales (ERP). Es docente universitario en el Departamento de Informática, en el Departamento de Gestión y Director de la Unidad de Gestión de Proyectos de Investigación de la Facultad Politécnica de la Universidad Nacional de Asunción.</p><p><strong>E-mail:</strong> ggonzalez@pol.una.py</p></div></div>`, visual: `<div class="visual-title">Trayectoria</div><div class="cards"><div class="card"><h3>FP-UNA</h3><p>Lic. en Análisis de Sistemas Informáticos</p></div><div class="card"><h3>Máster</h3><p>Ingeniería del Software - UPC Barcelona</p></div><div class="card"><h3>Certificación</h3><p>PMP - Project Management Professional</p></div><div class="card"><h3>Profesión</h3><p>Consultor TICs, Gestión de Proyectos, ERP</p></div></div>`, note: '<strong>Desarrollo:</strong> Fíjense en cómo la trayectoria combina Ingeniería de Software, gestión de proyectos y consultoría TICs; son perspectivas distintas sobre un mismo trabajo. El objetivo es entender el contexto docente y reconocer que un proyecto necesita responsabilidades complementarias.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): para construir el sistema de cambio de divisas, la gestión de proyectos puede coordinar alcance, plazos y riesgos, mientras la consultoría aporta experiencia en implementación de sistemas empresariales. Segundo contexto industrial: en una plataforma educativa, una persona puede relevar necesidades de docentes y estudiantes, y otra organizar la entrega con el equipo.<br><br><strong>Reflexión docente:</strong> La colaboración entre roles reduce puntos ciegos, aunque también exige acordar vocabulario y responsabilidades.<br><br><strong>Pregunta desafío:</strong> ¿qué decisiones tomaría un analista funcional que no tomaría un programador?<br><br><strong>Respuestas posibles:</strong> 1. Aclarar necesidades y reglas del negocio con las personas involucradas. 2. Analizar alternativas de alcance y priorizar requisitos antes de implementarlos. 3. Un programador puede aportar viabilidad técnica, pero no debería asumir automáticamente la decisión del negocio.<br><br><strong>Advertencia:</strong> presento la trayectoria como contexto docente, no como contenido evaluable.' },
  { title: 'Sobre La Asignatura', eyebrow: '03 · Organización', body: `<p><strong>Turno/Sección:</strong> Tarde-Q</p><p><strong>Horas cátedras semanales:</strong></p><ul><li>Clases teóricas: 36</li><li>Clases prácticas: 54</li></ul>`, visual: `<div class="visual-title">Distribución</div><div class="cards"><div class="card"><span class="number">36</span><p>Clases teóricas</p></div><div class="card"><span class="number">54</span><p>Clases prácticas</p></div></div>`, note: '<strong>Desarrollo:</strong> Veamos la sección y la distribución entre horas teóricas y horas prácticas: la teoría ayuda a construir conceptos y la práctica permite aplicarlos y revisarlos. La carga indicada organiza la cursada; no reemplaza la responsabilidad de preparar, producir y justificar el trabajo.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): podemos usar una clase teórica para analizar requisitos del cambio de divisas y una práctica para modelar una operación concreta. Segundo contexto industrial: en logística, una actividad práctica podría representar el flujo de un pedido y detectar dónde falta información.<br><br><strong>Reflexión docente:</strong> El aprendizaje se vuelve visible cuando una idea puede convertirse en una decisión o artefacto revisable.<br><br><strong>Pregunta desafío:</strong> ¿qué actividad práctica demostraría que una idea fue comprendida?<br><br><strong>Respuestas posibles:</strong> 1. Aplicar el concepto a un caso y explicar por qué la decisión es adecuada. 2. Elaborar un modelo, prueba o documento que otra persona pueda revisar. 3. Comparar una alternativa correcta con otra y justificar el trade-off.<br><br><strong>Advertencia:</strong> no confundan la distribución horaria con una garantía de dedicación total.' },
  { title: 'Metodología', eyebrow: '04 · Cómo trabajamos', body: `<ul><li>Las clases teóricas se desarrollarán en clases magistrales a cargo del docente y trabajo práctico a ser realizado por los estudiantes</li><li>Los estudiantes realizarán los trabajos prácticos en grupos y serán supervisados por los docentes</li><li>Presentación y defensa de trabajos prácticos relacionados con el área en cuestión</li><li>En la plataforma virtual se realizarán foros de discusión</li><li>Tutorías a distancia: individuales y/o grupales</li></ul>`, visual: `<div class="visual-title">Cinco movimientos</div><div class="cards"><div class="card"><h3>Exposición</h3><p>Clase magistral</p></div><div class="card"><h3>Práctica</h3><p>Trabajo grupal supervisado</p></div><div class="card"><h3>Defensa</h3><p>Presentación de resultados</p></div><div class="card"><h3>Foros</h3><p>Discusión virtual</p></div><div class="card"><h3>Tutorías</h3><p>Individuales o grupales</p></div></div>`, note: '<strong>Desarrollo:</strong> Les propongo combinar exposición, práctica, trabajo en equipo, defensa, foro y tutoría como partes de un mismo proceso de aprendizaje. La participación activa implica producir, recibir preguntas y revisar decisiones, no solo escuchar una explicación.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): un equipo puede presentar el flujo de una operación de cambio, defender sus supuestos en un foro y ajustar el modelo con tutoría. Segundo contexto industrial: en banca, un grupo podría justificar el flujo de una transferencia y responder qué controles aplicaría antes de liberarla.<br><br><strong>Reflexión docente:</strong> Defender una solución hace visible el razonamiento y puede revelar supuestos que una entrega aislada no muestra.<br><br><strong>Pregunta desafío:</strong> ¿qué evidencia mostraría que un grupo colaboró realmente?<br><br><strong>Respuestas posibles:</strong> 1. Un producto integrado, con decisiones y aportes trazables de sus integrantes. 2. La capacidad de explicar y defender el trabajo como equipo, no solo repartir diapositivas. 3. Cambios incorporados a partir de revisiones, foros o tutorías.<br><br><strong>Advertencia:</strong> participar no equivale solo a asistir; requiere producir y justificar decisiones.' },
  { title: 'Aula Virtual', eyebrow: '05 · Acceso', body: `<p><strong>Plataforma:</strong> Educa</p><p><strong>Nombre corto del aula virtual:</strong> ingsof1-av 2024</p><p><strong>Link de acceso al aula virtual:</strong><br><a href="https://grado.pol.una.py/course/view.php?id=6508">https://grado.pol.una.py/course/view.php?id=6508</a></p>`, visual: `<div class="visual-title">Educa</div><div class="quote">ingsof1-av 2024</div><p class="reference">El acceso se gestiona por el canal institucional correspondiente.</p>`, note: '<strong>Desarrollo:</strong> Fíjense en la plataforma, el nombre corto y el enlace del aula virtual; son datos para encontrar el espacio de trabajo y organizar el acceso. La seguridad exige tratar cualquier credencial por un canal seguro, separado de la documentación pública y versionada.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el aula puede centralizar el caso de cambio de divisas, sus entregas y las discusiones de equipo; el enlace identifica el espacio, pero la credencial no se comparte públicamente. Segundo contexto industrial: en un SaaS, una URL de administración puede documentarse, pero sus secretos deben gestionarse fuera del repositorio.<br><br><strong>Reflexión docente:</strong> Una exposición accidental de credenciales convierte un recurso académico en un incidente de seguridad; la prevención forma parte de la práctica profesional.<br><br><strong>Pregunta desafío:</strong> ¿qué harían si una contraseña aparece en un repositorio?<br><br><strong>Respuestas posibles:</strong> 1. Avisar al responsable y revocar o cambiar la credencial de inmediato. 2. Retirar el secreto del historial y revisar quién pudo acceder. 3. Registrar el incidente y evitar volver a publicar el valor en documentación o capturas.<br><br><strong>Advertencia:</strong> nunca expongan credenciales en notas, repositorios ni capturas públicas.' },
  { title: 'Sobre el Contenido', eyebrow: '06 · Recorrido', body: `<ul><li>Unidad I: Introducción a la Ingeniería de Software</li><li>Unidad II: Modelos de Proceso del Software</li><li>Unidad III: Ingeniería de Requerimientos</li><li>Unidad IV: Diseño del Software</li></ul>`, visual: `<div class="visual-title">Cuatro unidades</div><div class="cards"><div class="card"><span class="number">I</span><p>Introducción</p></div><div class="card"><span class="number">II</span><p>Procesos</p></div><div class="card"><span class="number">III</span><p>Requerimientos</p></div><div class="card"><span class="number">IV</span><p>Diseño</p></div></div>`, note: '<strong>Desarrollo:</strong> Observen el recorrido: la Unidad I introduce la disciplina; luego estudiaremos procesos, requerimientos y diseño. La secuencia va de comprender el problema y organizar el trabajo a decidir cómo construir una solución.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): primero entendemos el sistema de cambio de divisas, después acordamos qué debe hacer y recién entonces diseñamos su solución. Segundo contexto industrial: en salud, conviene relevar necesidades de pacientes y profesionales antes de diseñar un sistema de historias clínicas.<br><br><strong>Reflexión docente:</strong> Saltar etapas puede producir modelos elegantes para un problema mal entendido; el orden ayuda a reducir retrabajo.<br><br><strong>Pregunta desafío:</strong> ¿por qué conviene estudiar requerimientos antes del diseño?<br><br><strong>Respuestas posibles:</strong> 1. Porque los requerimientos expresan qué problema debe resolver el sistema. 2. Porque el diseño debe responder a restricciones y necesidades ya comprendidas. 3. Porque diseñar antes puede fijar una solución que luego contradiga al usuario o al negocio.<br><br><strong>Advertencia:</strong> el mapa anticipa temas; no reemplaza el desarrollo de cada unidad.' },
  { title: 'Sobre las Evaluaciones', eyebrow: '07 · Evaluación', body: `<div class="cards"><div class="card"><h3>Parciales</h3><p>Examen escrito <strong>30%</strong></p><p>Trabajo práctico <strong>70%</strong></p></div><div class="card"><h3>Final</h3><p>Examen escrito (Caso práctico) <strong>100%</strong></p></div></div>`, visual: `<div class="visual-title">Composición</div><div class="table-like"><div class="row"><strong>Parciales</strong><span>Examen escrito</span><b>30%</b></div><div class="row"><strong>Parciales</strong><span>Trabajo práctico</span><b>70%</b></div><div class="row"><strong>Final</strong><span>Examen escrito (Caso práctico)</span><b>100%</b></div></div>`, note: '<strong>Desarrollo:</strong> Revisemos la composición: en los parciales, el examen escrito representa 30% y el trabajo práctico 70%; el final es un examen escrito sobre un caso práctico, 100%. Un caso permite conectar conceptos, decisiones y justificaciones, no solo repetir definiciones.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): pueden justificar el diseño de una operación de cambio frente a un requisito de trazabilidad y luego analizar sus consecuencias en un caso escrito. Segundo contexto industrial: en transporte, un caso de asignación de viajes puede exigir explicar requisitos, riesgos y decisiones de diseño.<br><br><strong>Reflexión docente:</strong> La evaluación combina conocimiento y aplicación; prepararse solo para memorizar deja sin demostrar una parte central del trabajo profesional.<br><br><strong>Pregunta desafío:</strong> ¿cómo justificarían una decisión de diseño frente a un requisito?<br><br><strong>Respuestas posibles:</strong> 1. Vinculando la decisión con el requisito y con la necesidad que lo origina. 2. Explicando alternativas descartadas, riesgos y consecuencias. 3. Mostrando evidencia, como un modelo, prueba o criterio de aceptación.<br><br><strong>Advertencia:</strong> conserven exactamente los porcentajes del material.' },
  { title: 'Trabajos Prácticos', eyebrow: '08 · Hitos', body: `<ul><li>Formar equipos hasta 4 integrantes</li><li>Caso Práctico o Proyecto</li><li>Requerimientos (H1), Casos de Uso (H2), Especificación de Casos de Uso (H3)</li><li>Diagrama de Clases (H4), Diagrama de Secuencia (H5), Diagrama de Estados (H6), Diagrama de Actividades (H7), Diagrama  de Despliegue (H8)</li><li><strong>H - Hito</strong></li></ul>`, visual: `<div class="visual-title">Ruta incremental</div><div class="cards"><div class="card"><span class="number">H1–H3</span><p>Requerimientos y casos de uso</p></div><div class="card"><span class="number">H4–H8</span><p>Diagramas de análisis y diseño</p></div></div><p class="reference">Equipos: hasta 4 integrantes</p>`, note: '<strong>Desarrollo:</strong> Veamos la progresión del caso práctico o proyecto: un equipo de hasta cuatro integrantes construye evidencia mediante requerimientos, casos de uso, especificaciones y diagramas. La H significa Hito: cada punto de control permite revisar una parte del trabajo antes de avanzar.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): H1 puede aclarar requerimientos de tasas y fondos; los hitos siguientes pueden modelar casos de uso, clases, secuencias, estados, actividades y despliegue. Segundo contexto industrial: en logística, un proyecto puede pasar de requisitos de despacho a casos de uso y diagramas del seguimiento de paquetes.<br><br><strong>Reflexión docente:</strong> Trabajar incrementalmente reduce el riesgo de descubrir al final que todas las decisiones iniciales estaban mal orientadas, aunque cada hito requiere revisión real.<br><br><strong>Pregunta desafío:</strong> ¿qué riesgo aparece si se salta el hito de requerimientos?<br><br><strong>Respuestas posibles:</strong> 1. Diseñar o codificar funciones que no resuelven la necesidad real. 2. Generar inconsistencias entre casos de uso y diagramas posteriores. 3. Aumentar el retrabajo porque los errores se descubren tarde.<br><br><strong>Advertencia:</strong> un hito es un punto de control, no solo una fecha de entrega.' },
  { title: 'Bibliografía de Referencia', eyebrow: '09 · Lecturas', body: `<ul><li>SOMMERVILLE, Ian. Ingeniería de Software 6 y 7º Edición. Addison Wesley. 2002-2005</li><li>PRESSMAN, Roger 5º y 6º,7º Edición. Ingeniería del Software. Un enfoque práctico. McGraw-Hill. 2002-2005-2010</li><li>McCONNELL, Steve. Desarrollo y gestión de proyectos informáticos. McGraw-Hill. 1997</li><li>PIATTINI, Mario. Calidad de Sistemas Informáticos. Alfaomega - Ra-Ma. 2007</li></ul>`, visual: `<div class="visual-title">Biblioteca base</div><div class="quote">Sommerville · Pressman · McConnell · Piattini</div><p class="reference">Ediciones, editoriales y años según el material original.</p>`, note: '<strong>Desarrollo:</strong> Usemos esta bibliografía como conjunto de fuentes de referencia para ampliar conceptos y contrastar explicaciones. Respetemos la edición, editorial y año que aparecen en el material; una actualización bibliográfica debe identificarse como tal.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): podemos buscar en las referencias criterios para discutir el proceso de un sistema de cambio de divisas, sin atribuir al material una explicación que no contiene. Segundo contexto industrial: para un sistema gubernamental legado, distintas fuentes pueden ayudar a comparar mantenibilidad, riesgos y gestión del proyecto.<br><br><strong>Reflexión docente:</strong> Consultar fuentes no significa acumular citas: significa verificar conceptos y reconocer el alcance de cada afirmación.<br><br><strong>Pregunta desafío:</strong> ¿qué afirmación del slide buscarían verificar en una fuente?<br><br><strong>Respuestas posibles:</strong> 1. Una definición de Ingeniería de Software o de proceso. 2. Una comparación entre productos genéricos y hechos a medida. 3. Una recomendación cuya aplicabilidad dependa del contexto.<br><br><strong>Advertencia:</strong> no presenten una edición o año actualizado como si perteneciera al material original.' },
  { title: 'UNIDAD I – INTRODUCCIÓN A LA INGENIERÍA DE SOFTWARE', eyebrow: '10 · Cambio de bloque', body: `<p class="lede">INGENIERÍA DE SOFTWARE I</p><p>Prof. Lic. Guillermo Jacobo González Rodas Mst. PMP</p>`, visual: `<div class="visual-title">Unidad I</div><div class="quote">Introducción a la Ingeniería de Software</div>`, note: '<strong>Desarrollo:</strong> Ahora pasemos de la organización del curso a la Unidad I: Introducción a la Ingeniería de Software. En esta unidad vamos a construir el vocabulario para hablar de productos, procesos, costos, retos y responsabilidad profesional.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): usemos el sistema de cambio de divisas como caso para observar cómo una disciplina organiza decisiones más allá del código. Segundo contexto industrial: un sistema de transporte permite estudiar problemas similares de requisitos, operación, mantenimiento y evolución.<br><br><strong>Reflexión docente:</strong> Este cambio de registro importa: comprender el curso ayuda a participar, pero comprender la disciplina permite tomar mejores decisiones profesionales.<br><br><strong>Pregunta desafío:</strong> ¿qué problema profesional esperan que la unidad ayude a comprender?<br><br><strong>Respuestas posibles:</strong> 1. Cómo producir software confiable y mantenible. 2. Cómo organizar un proceso para reducir errores y retrabajo. 3. Cómo equilibrar necesidades del negocio, restricciones técnicas y responsabilidad.<br><br><strong>Advertencia:</strong> no adelanten conclusiones antes de presentar los conceptos.' },
  { title: 'OBJETIVOS', eyebrow: '11 · Resultados esperados', body: `<ul><li>Definir la Ingeniería de Software y explicar su importancia</li><li>Discutir los conceptos de Producto de Software y Proceso de Software</li><li>Introducir la noción de responsabilidad profesional de un ingeniero de software.</li></ul>`, visual: `<div class="visual-title">Al finalizar</div><div class="cards"><div class="card"><span class="number">01</span><p>Definir la Ingeniería de Software</p></div><div class="card"><span class="number">02</span><p>Discutir producto y proceso</p></div><div class="card"><span class="number">03</span><p>Introducir responsabilidad</p></div></div>`, note: '<strong>Desarrollo:</strong> Tomemos los objetivos como criterios de aceptación: debemos poder definir Ingeniería de Software, discutir producto y proceso, e introducir la responsabilidad profesional. Al cierre, volvamos a ellos para comprobar si podemos explicar y aplicar cada idea.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): definamos producto y proceso a partir del sistema de cambio de divisas y discutamos qué responsabilidades aparecen al manejar fondos y auditoría. Segundo contexto industrial: en educación, una plataforma de evaluaciones exige pensar en confiabilidad, privacidad y consecuencias para sus usuarios.<br><br><strong>Reflexión docente:</strong> Un objetivo se demuestra con evidencia: repetir una frase no alcanza si no podemos usarla para razonar sobre un caso.<br><br><strong>Pregunta desafío:</strong> ¿cómo demostrarían que pueden definir y no solo repetir un término?<br><br><strong>Respuestas posibles:</strong> 1. Explicándolo con palabras propias y distinguiéndolo de conceptos cercanos. 2. Aplicándolo a un caso y justificando qué elementos lo muestran. 3. Comparando ejemplos y contraejemplos.<br><br><strong>Advertencia:</strong> distingan conocer una definición de aplicarla a un caso.' },
  { title: 'CONTENIDO', eyebrow: '12 · Mapa de la unidad', body: `<ul><li>La Ingeniería de Software</li><li>Productos Software</li><li>Costos del Software</li><li>Proceso de Software</li><li>Retos de la Ingeniería de Software</li></ul>`, visual: `<div class="visual-title">Secuencia</div><div class="sequence-card" aria-label="Secuencia temática de la unidad"><div class="sequence-step"><span class="sequence-index">01</span><strong>Disciplina</strong><small>Qué es y por qué importa</small></div><div class="sequence-step"><span class="sequence-index">02</span><strong>Productos</strong><small>Qué construimos</small></div><div class="sequence-step"><span class="sequence-index">03</span><strong>Costos</strong><small>Qué debemos controlar</small></div><div class="sequence-step"><span class="sequence-index">04</span><strong>Proceso</strong><small>Cómo lo desarrollamos</small></div><div class="sequence-step"><span class="sequence-index">05</span><strong>Retos</strong><small>Qué exige la profesión</small></div></div>`, note: '<strong>Desarrollo:</strong> Observen el mapa: iremos de la disciplina a los productos, costos, procesos y retos de la Ingeniería de Software. La secuencia organiza la conversación, pero los temas se conectan: el proceso influye en costos y los retos condicionan las decisiones.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): relacionemos el producto de cambio de divisas con su costo de desarrollo, el proceso de construcción y los retos de integrarlo con servicios externos. Segundo contexto industrial: en una solución de comercio, mantenimiento, volumen de usuarios y entregas pueden modificar tanto el proceso como el costo.<br><br><strong>Reflexión docente:</strong> Pensar cada tema de forma aislada oculta trade-offs; la ingeniería consiste en conectar decisiones con sus consecuencias.<br><br><strong>Pregunta desafío:</strong> ¿cómo se relacionan costo y proceso?<br><br><strong>Respuestas posibles:</strong> 1. Un proceso con controles puede requerir más esfuerzo inicial y reducir retrabajo. 2. Un proceso poco claro puede abaratar el inicio, pero aumentar fallos y mantenimiento. 3. El contexto determina qué inversión produce una mejora razonable.<br><br><strong>Advertencia:</strong> el orden organiza la explicación, pero los temas están conectados.' },
  { title: '¿Qué es la Ingeniería de Software?', eyebrow: '13 · Definición', body: `<div class="card"><p><strong>La ingeniería del software es una disciplina que comprende todos los aspectos de la producción del software desde las etapas iniciales de la especificación del sistema hasta el mantenimiento de éste después de que se utiliza. (Definición de Ian Somerville)</strong></p><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005.</p></div><ul><li>La Ingeniería de Software es una disciplina de la Ingeniería que concierne a todos los aspectos de la producción de software</li><li>Establecimiento y uso de principios con caracteres de ingeniería apropiados para obtener, software confiable, que opere eficaz y eficientemente en máquinas reales</li><li>Establecimiento y uso de métodos, herramientas y procedimientos, orientados a obtener software económico que sea fiable y funcione de manera eficiente</li></ul>`, visual: `<div class="visual-title">Alcance</div><div class="cards"><div class="card"><h3>Especificación</h3><p>Etapas iniciales</p></div><div class="card"><h3>Producción</h3><p>Principios, métodos y herramientas</p></div><div class="card"><h3>Mantenimiento</h3><p>Después del uso</p></div></div>`, note: '<strong>Desarrollo:</strong> Veamos la Ingeniería de Software como una disciplina que abarca la especificación, la producción y el mantenimiento. Comparen las formulaciones del slide: unas enfatizan alcance y ciclo de vida; otras, principios, métodos, herramientas, confiabilidad, eficiencia y costo.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): para el sistema de cambio de divisas debemos especificar reglas, producir una solución, verificar operaciones y mantenerla cuando cambien las tasas o integraciones. Segundo contexto industrial: una aplicación de turnos médicos necesita esas mismas actividades para operar confiablemente y adaptarse a nuevas necesidades.<br><br><strong>Reflexión docente:</strong> La mirada profesional distribuye la prevención a lo largo del ciclo; esperar al final para descubrir fallos suele limitar las alternativas.<br><br><strong>Pregunta desafío:</strong> ¿en qué etapa se puede prevenir un fallo costoso?<br><br><strong>Respuestas posibles:</strong> 1. Desde la especificación, aclarando necesidades y restricciones. 2. Durante diseño y desarrollo, revisando decisiones antes de hacerlas más costosas de cambiar. 3. En validación, detectando evidencia insuficiente antes de la operación.<br><br><strong>Advertencia:</strong> Ingeniería de Software no es únicamente escribir código.' },
  { title: '¿Qué es el Software?', eyebrow: '14 · Definiciones', body: `<div class="cards"><div class="card"><h3>Sommerville:</h3><p>“Programas de cómputo y su documentación asociada”</p><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005.</p></div><div class="card"><h3>Pressman:</h3><p>“Elemento del sistema de información que es lógico, con características considerablemente distintas a las del hardware”</p><p class="reference">Pressman, R. Ingeniería del Software: Un enfoque práctico, 7ª ed. McGraw-Hill, 2010.</p></div></div>`, visual: `<div class="visual-title">Dos énfasis</div><div class="quote">Programas + documentación<br><br>Elemento lógico ≠ hardware</div>`, note: '<strong>Desarrollo:</strong> Contrastemos las definiciones: el software incluye programas y documentación asociada, y es un elemento lógico distinto del hardware. La documentación sostiene el uso, la operación y el mantenimiento; por eso forma parte del producto considerado en el slide.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): además del programa de cambio de divisas, necesitamos documentar reglas, operación, errores e integración con pagos. Segundo contexto industrial: un sistema legado de gobierno puede seguir funcionando, pero sin documentación su mantenimiento depende de conocimiento difícil de transferir.<br><br><strong>Reflexión docente:</strong> Tratar la documentación como un accesorio aumenta la dependencia de personas y el riesgo de operar o cambiar el sistema sin comprenderlo.<br><br><strong>Pregunta desafío:</strong> ¿qué documento asociarían a un sistema real?<br><br><strong>Respuestas posibles:</strong> 1. Manual de usuario o procedimiento operativo. 2. Especificación de requisitos, diseño o interfaz de integración. 3. Instrucciones de despliegue, mantenimiento y recuperación ante fallos.<br><br><strong>Advertencia:</strong> lógico no significa intangible o irrelevante para la operación física.' },
  { title: 'Productos de Software', eyebrow: '15 · Tipos', body: `<ul><li><strong>Productos genéricos:</strong> Productos que son producidos por una organización para ser comercializados.</li><li><strong>Productos hechos a medida:</strong> Sistemas que son desarrollados bajo pedido a un desarrollador específico.</li></ul><p>La mayor parte del gasto del software se realiza en productos genéricos, pero existe un mayor esfuerzo en el desarrollo de los sistemas hechos a medida.</p><p class="reference">Sommerville, I. Ingeniería de Software, 7ª ed. Addison Wesley, 2005. Cap. 1.</p>`, visual: `<div class="visual-title">Comparación</div><div class="table-like"><div class="row"><strong>Genéricos</strong><span>Para comercializar</span><b>Mayor gasto</b></div><div class="row"><strong>A medida</strong><span>Bajo pedido</span><b>Mayor esfuerzo</b></div></div>`, note: '<strong>Desarrollo:</strong> Distingamos productos genéricos, producidos para comercializarse a varias organizaciones, de productos hechos a medida, desarrollados bajo pedido. El slide señala una diferencia entre gasto y esfuerzo: debemos conservarla como comparación del material, no como una ley universal.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): una plataforma genérica de cambio puede servir a varias empresas, mientras una solución hecha a medida puede integrar reglas y sistemas particulares de una entidad financiera. Segundo contexto industrial: un hospital puede comprar un producto estándar o encargar un sistema adaptado a sus circuitos y regulaciones.<br><br><strong>Reflexión docente:</strong> Pasar de un cliente a muchos amplía la necesidad de configurar, documentar y sostener variaciones; la reutilización trae oportunidades y restricciones.<br><br><strong>Pregunta desafío:</strong> ¿qué decisión cambia al pasar de un cliente a muchos?<br><br><strong>Respuestas posibles:</strong> 1. Qué requisitos se consideran parte del producto común y cuáles serán configurables. 2. Cómo se priorizan cambios que afectan a varios clientes. 3. Qué estrategia de soporte, documentación y evolución se necesita.<br><br><strong>Advertencia:</strong> no conviertan la comparación del slide en una regla para todos los mercados.' },
  { title: 'Características de Productos Software', eyebrow: '16 · Calidad del producto', body: `<div class="cards"><div class="card"><h3>Mantenibles</h3><p>El software debe evolucionar y seguir cumpliendo con sus especificaciones.</p></div><div class="card"><h3>Confiabilidad</h3><p>El software no debe causar daños físicos o económicos en el caso de fallos.</p></div><div class="card"><h3>Eficiencia</h3><p>El software no debe desperdiciar los recursos del sistema.</p></div><div class="card"><h3>Utilización adecuada</h3><p>El software debe contar con una interfaz de usuario y documentación adecuada.</p></div></div>`, visual: `<div class="visual-title">Cuatro características</div><div class="quote">Mantenibles · Confiabilidad · Eficiencia · Utilización adecuada</div>`, note: '<strong>Desarrollo:</strong> Recorramos las características: mantenibilidad permite evolucionar, confiabilidad evita daños ante fallos, eficiencia cuida los recursos y utilización adecuada reúne interfaz y documentación apropiadas. No las tratemos como etiquetas decorativas: cada una expresa una condición que debemos observar en el producto.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): el sistema debe adaptarse a nuevas tasas, manejar fallos sin afectar fondos, responder sin desperdiciar recursos y orientar correctamente a quien realiza una operación. Segundo contexto industrial: en un sistema de salud, confiabilidad y utilización adecuada pueden ser especialmente visibles en alertas, permisos y documentación para el personal.<br><br><strong>Reflexión docente:</strong> Mejorar un atributo puede exigir costos o compromisos en otros; la prioridad debe justificarse por el contexto y el impacto.<br><br><strong>Pregunta desafío:</strong> ¿qué atributo priorizarían en un sistema crítico y por qué?<br><br><strong>Respuestas posibles:</strong> 1. Confiabilidad, si un fallo puede causar daño económico o físico. 2. Mantenibilidad, si el entorno cambia y el sistema deberá evolucionar durante años. 3. Eficiencia, si los recursos son limitados y afectan la operación. 4. Utilización adecuada, si errores de comprensión pueden comprometer el servicio.<br><br><strong>Advertencia:</strong> mejorar un atributo puede exigir costos o compromisos en otros.' },
  { title: 'Importancia de las Características', eyebrow: '17 · Contexto', body: `<p>La importancia relativa de las características depende en el tipo de producto y en el ambiente en el que será utilizado.</p><p>En algunos casos, algunos atributos pueden predominar. En sistemas de seguridad críticos de tiempo real, los atributos clave pueden ser la confiabilidad y la eficiencia.</p><p>Los costos tienden a crecer exponencialmente si son requeridos altos niveles de alguna característica.</p>`, visual: `<div class="visual-title">La prioridad depende</div><div class="cards"><div class="card"><h3>Producto</h3><p>Tipo de sistema</p></div><div class="card"><h3>Ambiente</h3><p>Contexto de utilización</p></div><div class="card"><h3>Exigencia</h3><p>Puede elevar los costos</p></div></div>`, note: '<strong>Desarrollo:</strong> La importancia relativa de una característica depende del tipo de producto y del ambiente donde se usa. En sistemas de seguridad crítica y tiempo real, el slide destaca confiabilidad y eficiencia; también advierte que exigir niveles altos puede elevar los costos.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): una operación financiera puede priorizar confiabilidad y trazabilidad, mientras una consulta pública de tasas puede tolerar otra combinación de atributos. Segundo contexto industrial: un sistema de control médico puede priorizar confiabilidad de forma distinta que una aplicación de entretenimiento.<br><br><strong>Reflexión docente:</strong> No existe una prioridad profesional fuera de contexto: sacrificar un atributo puede ser razonable en un caso y peligroso en otro.<br><br><strong>Pregunta desafío:</strong> ¿qué atributo sacrificarían menos en cada caso?<br><br><strong>Respuestas posibles:</strong> 1. En control médico, confiabilidad, porque el impacto de un fallo puede ser crítico. 2. En una aplicación de entretenimiento, quizá eficiencia o disponibilidad según el uso, sin ignorar seguridad. 3. En una operación financiera, confiabilidad y trazabilidad antes que una mejora superficial de velocidad.<br><br><strong>Advertencia:</strong> el slide expresa una tendencia cualitativa; no aporta una fórmula de costos.' },
  { title: 'Clasificación de Productos Software', eyebrow: '18 · Taxonomía', body: `<div class="cards"><div class="card"><h3>Por su estructura:</h3><ul><li>Funcionales.</li><li>Orientados a objetos.</li><li>Orientados a listas.</li><li>Orientados a componentes.</li></ul></div><div class="card"><h3>Por su función:</h3><ul><li>Programas o Sistemas de Usuario</li><li>Herramientas de Software.</li><li>Librerías.</li><li>Sistemas de uso genérico: Compiladores, S.O’s, Procesadores de Texto, etc.</li><li>Bases de Datos.</li><li>Sistemas basados en Web.</li></ul></div><div class="card"><h3>Por su plataforma de cómputo:</h3><ul><li>Sistemas embebidos o empotrados.</li><li>Sistemas de cómputo distribuído</li><li>Sistemas de tiempo real.</li><li>Sistemas basados en Chips.</li><li>Sistemas de cómputo ubicuos.</li></ul></div></div>`, visual: `<div class="visual-title">Tres criterios</div><div class="quote">Estructura<br>Función<br>Plataforma de cómputo</div>`, note: 'Presentar los tres ejes de clasificación y recorrer sus ejemplos. Conservar la jerarquía para que se entienda que cada grupo pertenece a un criterio diferente. Términos clave: estructura, función, plataforma, embebido, distribuido, web y tiempo real. Ejemplo/analogía: el mismo sistema puede clasificarse por cómo está construido, qué hace y dónde se ejecuta. Pregunta desafío: ¿qué clasificaciones aplicarían a una aplicación móvil? Advertencia: no mezclar criterios como si fueran categorías excluyentes.' },
  { title: 'Costos del Software', eyebrow: '19 · Eficiencia', body: `<ul><li>Los costos del software a menudo dominan al costo del sistema</li><li>Cuesta más mantener el software que desarrollarlo</li><li>La Ingeniería de Software concierne a un desarrollo efectivo en cuanto a costos del software</li></ul>`, visual: `<div class="visual-title">Relación indicada por la fuente</div><svg class="chart" viewBox="0 0 420 280" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Costos frente a Eficiencia</title><desc id="chart-desc">Ejes sin valores numéricos y curva ascendente que se eleva con rapidez hacia la derecha.</desc><line class="guide" x1="58" y1="56" x2="58" y2="232"></line><line class="guide" x1="58" y1="232" x2="390" y2="232"></line><line class="axis" x1="58" y1="232" x2="390" y2="232"></line><line class="axis" x1="58" y1="232" x2="58" y2="38"></line><path class="curve" d="M72 219 C170 218 230 207 278 182 C326 157 350 103 375 48"></path><text x="12" y="50">Costos</text><text x="292" y="266">Eficiencia</text></svg>`, note: '<strong>Desarrollo:</strong> Leamos las afirmaciones sobre costos: pueden dominar el costo del sistema, el mantenimiento puede superar al desarrollo y la Ingeniería de Software busca un desarrollo efectivo en costos. El gráfico relaciona visualmente costos y eficiencia, pero no aporta valores ni una fórmula.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): una arquitectura difícil de cambiar puede volver costoso adaptar tasas, fondos o integraciones, aunque la primera versión haya sido rápida. Segundo contexto industrial: un sistema legado de transporte puede requerir más mantenimiento que desarrollo cuando cada cambio rompe integraciones antiguas.<br><br><strong>Reflexión docente:</strong> La eficiencia profesional incluye pensar el costo futuro; ahorrar hoy sin cuidar mantenibilidad puede trasladar el problema a toda la vida del sistema.<br><br><strong>Pregunta desafío:</strong> ¿qué decisión temprana reduciría el costo futuro?<br><br><strong>Respuestas posibles:</strong> 1. Aclarar requisitos y restricciones antes de comprometer una solución. 2. Diseñar puntos de cambio y registrar decisiones para facilitar mantenimiento. 3. Validar temprano las integraciones o riesgos que podrían generar retrabajo.<br><br><strong>Advertencia:</strong> el gráfico expresa una relación cualitativa; no permite inferir valores ni una fórmula.' },
  { title: 'Proceso de Software', eyebrow: '20 · Actividades', body: `<p><strong>Conjunto estructurado de actividades requeridas para desarrollar un sistema de software.</strong></p><ul><li><strong>Especificación</strong> – que debe hacer el software y cuáles son sus especificaciones de desarrollo.</li><li><strong>Desarrollo</strong> – producción del sistema de software.</li><li><strong>Validación</strong> – verificar que el software hace lo que el cliente pide.</li><li><strong>Evolución</strong> – cambiar/adaptar el software a las demandas.</li></ul><p>Las actividades varían dependiendo de la organización y del tipo de sistema a desarrollarse.</p><p>Debe estar explícitamente modelado si va a ser bien administrado</p>`, visual: `<div class="visual-title">Ciclo de actividades</div><div class="process"><span>Especificación</span><span>Desarrollo</span><span>Validación</span><span>Evolución</span></div>`, note: '<strong>Desarrollo:</strong> Definamos el proceso de software como un conjunto estructurado de actividades: especificación, desarrollo, validación y evolución. Las actividades varían según la organización y el sistema; modelarlas explícitamente ayuda a administrarlas sin asumir que existe una receta única.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): especificamos reglas de cambio, desarrollamos la solución, validamos cálculos y evolucionamos el sistema cuando cambian tasas o servicios externos. Segundo contexto industrial: un sistema de turnos puede adaptar su proceso según la criticidad, privacidad y cantidad de integraciones.<br><br><strong>Reflexión docente:</strong> Modelar el proceso mejora la visibilidad, pero no debe convertir el trabajo en una secuencia rígida incapaz de responder a evidencia nueva.<br><br><strong>Pregunta desafío:</strong> ¿qué evidencia ubicarían en cada actividad?<br><br><strong>Respuestas posibles:</strong> 1. Especificación: requisitos, restricciones y criterios de aceptación. 2. Desarrollo: diseño, código y decisiones de construcción. 3. Validación: pruebas, revisiones y evidencia de que se cumple lo pedido. 4. Evolución: cambios priorizados, incidentes y nuevas necesidades.<br><br><strong>Advertencia:</strong> modelar el proceso no significa volverlo rígido.' },
  { title: 'Proceso Genérico', eyebrow: '21 · Secuencia', body: `<ul><li><strong>Especificación</strong> - establecer los requerimientos y restricciones del sistema.</li><li><strong>Diseño</strong> - Producir un modelo del sistema.</li><li><strong>Codificación</strong> - construir el sistema.</li><li><strong>Prueba</strong> - verificar que el sistema cumpla con las especificaciones requeridas.</li><li><strong>Instalación</strong> - entregar el sistema al usuario y asegurar su operacionalidad.</li><li><strong>Mantenimiento</strong> - reparar fallos en el sistema cundo sea descubiertos</li></ul>`, visual: `<div class="visual-title">De la idea al uso</div><div class="process"><span>Especificación</span><span>Diseño</span><span>Codificación</span><span>Prueba</span><span>Instalación</span><span>Mantenimiento</span></div>`, note: '<strong>Desarrollo:</strong> Recorramos el proceso genérico: establecer requerimientos, producir el diseño, realizar la codificación, ejecutar la prueba, completar la instalación y sostener el mantenimiento. Cada actividad tiene un propósito distinto, aunque en la práctica podamos volver atrás con nueva evidencia.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): acordamos cómo se calcula una operación, modelamos la solución, codificamos, probamos fondos y pagos, instalamos y luego corregimos fallos. Segundo contexto industrial: en comercio electrónico, probar el checkout antes de instalarlo evita que una ambigüedad de requerimientos llegue a producción.<br><br><strong>Reflexión docente:</strong> La secuencia ordena el trabajo, pero no elimina la incertidumbre; el riesgo crece cuando se confunde avanzar con comprender.<br><br><strong>Pregunta desafío:</strong> ¿qué error aparece si se codifica antes de acordar el requerimiento?<br><br><strong>Respuestas posibles:</strong> 1. Construir una solución técnicamente válida para una necesidad equivocada. 2. Aumentar cambios, discusiones y retrabajo cuando el requerimiento se aclare. 3. Dificultar la prueba porque no existe un criterio acordado contra el cual comparar.<br><br><strong>Advertencia:</strong> la secuencia ayuda a organizar, pero el trabajo real puede requerir retrocesos.' },
  { title: 'Características del Proceso', eyebrow: '22 · Lista de comprobación', body: `<div class="cards"><div class="card"><h3>Entendible</h3><p>Se encuentra el proceso bien definido y es entendible ?</p></div><div class="card"><h3>Visible</h3><p>El proceso es visible al exterior ?</p></div><div class="card"><h3>Soportable</h3><p>Puede el proceso ser soportado por herramientas CASE ?</p></div><div class="card"><h3>Aceptable</h3><p>El proceso es aceptado por aquellos involucrados en el ?</p></div><div class="card"><h3>Confiable</h3><p>Errores del proceso son descubiertos antes de que se conviertan en errores del producto ?</p></div><div class="card"><h3>Robusto</h3><p>Puede continuar el proceso a pesar de problemas inesperados ?</p></div><div class="card"><h3>Mantenible</h3><p>Puede el proceso evolucionar para cumplir con los objetivos organizacionales ?</p></div><div class="card"><h3>Rapidez</h3><p>Qué tan rápido puede producirse el sistema ?</p></div></div>`, visual: `<div class="visual-title">Preguntas del proceso</div><div class="quote">Entendible · Visible · Soportable · Aceptable · Confiable · Robusto · Mantenible · Rapidez</div>`, note: '<strong>Desarrollo:</strong> Usemos estas preguntas como una lista de comprobación de entendibilidad, visibilidad, soporte, aceptación, confiabilidad, robustez, mantenibilidad y rapidez. Cada característica observa un aspecto diferente del proceso; juntas permiten detectar debilidades antes de atribuirlas solo al producto.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): revisemos si el proceso hace visibles las decisiones sobre tasas, acepta a los roles involucrados, resiste fallos de pago y puede evolucionar con nuevas reglas. Segundo contexto industrial: en logística, un proceso puede ser rápido pero frágil si no hace visibles excepciones, dependencias o pruebas de entregas.<br><br><strong>Reflexión docente:</strong> La rapidez es atractiva, pero un proceso que produce velozmente errores o retrabajo no es profesionalmente eficaz.<br><br><strong>Pregunta desafío:</strong> ¿qué indicador revelaría primero un proceso frágil?<br><br><strong>Respuestas posibles:</strong> 1. Requisitos que cambian sin trazabilidad ni aceptación clara. 2. Errores del proceso que se descubren recién durante la operación. 3. Bloqueos ante problemas inesperados o dependencia de una sola persona. 4. Entregas rápidas acompañadas de defectos y retrabajo frecuentes.<br><br><strong>Advertencia:</strong> rapidez aislada no equivale a calidad.' },
  { title: 'Problemas en el Proceso', eyebrow: '23 · Riesgos habituales', body: `<p><strong>Normalmente…</strong></p><ul><li>Las especificaciones son incompletas o anómalas.</li><li>No existe una distinción precisa entre la especificación, el diseño y la codificación.</li><li>Solo hasta que el sistema se ha producido se puede probar.</li><li>El software no siempre se puede remplazar durante el mantenimiento</li></ul>`, visual: `<div class="visual-title">Puntos de atención</div><div class="cards"><div class="card"><h3>Especificación</h3><p>Incompleta o anómala</p></div><div class="card"><h3>Separación</h3><p>Fronteras poco precisas</p></div><div class="card"><h3>Prueba</h3><p>Demasiado tardía</p></div><div class="card"><h3>Mantenimiento</h3><p>Reemplazo no siempre posible</p></div></div>`, note: '<strong>Desarrollo:</strong> Analicemos los problemas habituales: especificaciones incompletas o anómalas, poca distinción entre especificación, diseño y codificación, prueba tardía y dificultad para reemplazar software durante el mantenimiento. La palabra normalmente importa: el slide describe riesgos frecuentes, no resultados inevitables.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): si no aclaramos una regla de conversión y recién probamos al final, podemos descubrir tarde que el sistema afecta saldos o auditoría. Segundo contexto industrial: en un sistema legado gubernamental, una pieza antigua puede no poder reemplazarse sin interrumpir servicios esenciales.<br><br><strong>Reflexión docente:</strong> La prevención temprana no elimina todos los problemas, pero conserva más opciones y reduce el impacto de corregirlos.<br><br><strong>Pregunta desafío:</strong> ¿qué revisión temprana habría reducido el impacto?<br><br><strong>Respuestas posibles:</strong> 1. Revisar requisitos con usuarios y responsables del negocio. 2. Separar y revisar el modelo de diseño antes de codificar. 3. Probar riesgos e integraciones antes de completar todo el sistema.<br><br><strong>Advertencia:</strong> estos son problemas habituales, no afirmaciones inevitables.' },
  { title: 'Retos de los Ingenieros de Software', eyebrow: '24 · Contexto profesional', body: `<ul><li><strong>Mantener y tratar con sistemas legados;</strong> sistemas antiguos que deben ser mantenidos y mejorados</li><li><strong>Heterogeneidad:</strong> Sistemas que incluyen distintas plataformas de software y hardware</li><li><strong>Entrega:</strong> Existe una presión incremental por una entrega a tiempo de los productos de software</li><li><strong>Formalidad:</strong> Existe una gran demanda de que exista formalidad en el proceso de desarrollo de software</li></ul>`, visual: `<div class="visual-title">Cuatro retos</div><div class="quote">Legados<br>Heterogeneidad<br>Entrega<br>Formalidad</div>`, note: '<strong>Desarrollo:</strong> Cerremos con cuatro retos: mantener sistemas legados, enfrentar la heterogeneidad, entregar a tiempo y responder a la demanda de formalidad en el proceso. Estos retos combinan restricciones técnicas, organizacionales y profesionales; no se resuelven solo agregando código.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): integrar tasas, pagos y auditoría puede mezclar plataformas y servicios heterogéneos mientras el negocio exige una entrega puntual. Segundo contexto industrial: un sistema de transporte legado puede tener que convivir con una aplicación móvil nueva sin detener la operación.<br><br><strong>Reflexión docente:</strong> La presión por entregar puede empujar atajos, pero no elimina la responsabilidad de hacer visibles riesgos y límites.<br><br><strong>Pregunta desafío:</strong> ¿qué riesgo investigarían primero?<br><br><strong>Respuestas posibles:</strong> 1. Dependencias del sistema legado que podrían romperse con el cambio. 2. Incompatibilidades entre plataformas, datos o integraciones. 3. Un requisito crítico que no pueda validarse dentro del plazo. 4. La ausencia de evidencia y formalidad para justificar la entrega.<br><br><strong>Advertencia:</strong> la presión por entregar no elimina la responsabilidad profesional.' },
  { title: 'Muchas gracias', eyebrow: '25 · Cierre', body: `<div class="quote">“Pues al igual que un arquitecto es esencial para construir una casa que no se venga abajo, un ingeniero del software es esencial para construir software eficiente, seguro y mantenible (que es el que la gente querrá usar).”</div>`, visual: `<div class="visual-title">Síntesis</div><p>La ingeniería de software hace posible construir productos que las personas querrán usar.</p>`, note: '<strong>Desarrollo:</strong> Cerremos retomando eficiencia, seguridad, mantenibilidad y responsabilidad profesional: la ingeniería busca que el software funcione hoy y siga siendo confiable mañana. La cita usa la arquitectura como analogía para recordar que las decisiones estructurales afectan estabilidad, cambios y formas de uso.<br><br><strong>Ejemplos:</strong> Global Exchange (conductor): las personas querrán seguir usando el sistema si las operaciones son claras, seguras, eficientes y sostenibles ante cambios de tasas o integraciones. Segundo contexto industrial: en una plataforma educativa, mantener confianza requiere cuidar disponibilidad, datos y facilidad de evolución.<br><br><strong>Reflexión docente:</strong> La calidad profesional se mide también por el impacto en quienes dependen del sistema, no solo por si el código compila o la entrega llega a tiempo.<br><br><strong>Pregunta desafío:</strong> ¿qué decisión de ingeniería hace que las personas quieran seguir usando el sistema?<br><br><strong>Respuestas posibles:</strong> 1. Diseñar una experiencia comprensible y adecuada al contexto de uso. 2. Proteger datos y operaciones mediante controles proporcionales al riesgo. 3. Invertir en mantenibilidad para corregir y evolucionar sin degradar el servicio. 4. Validar con evidencia que el sistema cumple lo que las personas necesitan.<br><br><strong>Advertencia:</strong> la analogía orienta la comprensión, pero no equipara literalmente ambas profesiones.' }
];

const stage = document.querySelector('#stage');
const indexPanel = document.querySelector('#index-panel');
const notesPanel = document.querySelector('#notes-panel');
const index = document.querySelector('#slide-index');
const notes = document.querySelector('#speaker-notes');
const printAll = new URLSearchParams(location.search).get('print') === 'all';
let current = 0;

function slideMarkup(slide, position) {
  return `<article class="slide slide-${position + 1}" aria-labelledby="slide-title"><div><p class="eyebrow">${slide.eyebrow}</p><h1 id="slide-title">${slide.title}</h1><div class="content">${slide.body}</div></div><div class="visual">${slide.visual}</div><span class="slide-number">${String(position + 1).padStart(2, '0')}</span></article>`;
}

function render() {
  const slide = slides[current];
  stage.innerHTML = slideMarkup(slide, current);
  document.querySelector('#counter').textContent = `${String(current + 1).padStart(2, '0')} / ${String(slides.length).padStart(2, '0')}`;
  const progress = document.querySelector('#progress');
  progress.style.width = `${((current + 1) / slides.length) * 100}%`;
  progress.setAttribute('aria-valuenow', current + 1);
  notes.innerHTML = `<div class="note"><strong>Slide ${current + 1}: ${slide.title}</strong><p>${slide.note}</p></div>`;
  document.querySelectorAll('.index-item').forEach((button, i) => button.classList.toggle('active', i === current));
  history.replaceState(null, '', `#slide-${current + 1}`);
}
function renderAllForPrint() { stage.innerHTML = slides.map((slide, position) => slideMarkup(slide, position)).join(''); }
function goTo(position) { current = Math.max(0, Math.min(slides.length - 1, position)); render(); document.querySelector('#main-content').focus({ preventScroll: true }); }
function toggle(panel, force) { const open = typeof force === 'boolean' ? force : !panel.classList.contains('open'); panel.classList.toggle('open', open); panel.setAttribute('aria-hidden', String(!open)); const control = document.querySelector(`[aria-controls="${panel.id}"]`); if (control) control.setAttribute('aria-expanded', String(open)); if (open) panel.querySelector('button, [href]')?.focus(); }
slides.forEach((slide, i) => { const button = document.createElement('button'); button.className = 'index-item'; button.type = 'button'; button.textContent = `${String(i + 1).padStart(2, '0')} · ${slide.title}`; button.addEventListener('click', () => { goTo(i); toggle(indexPanel, false); }); index.append(button); });
document.querySelector('#next').addEventListener('click', () => goTo(current + 1));
document.querySelector('#previous').addEventListener('click', () => goTo(current - 1));
document.querySelector('#index-toggle').addEventListener('click', () => toggle(indexPanel));
document.querySelector('#notes-toggle').addEventListener('click', () => toggle(notesPanel));
document.querySelectorAll('.close-panel').forEach(button => button.addEventListener('click', () => toggle(document.querySelector(`#${button.dataset.close}`), false)));
document.querySelector('#fullscreen').addEventListener('click', () => document.documentElement.requestFullscreen?.());
document.addEventListener('keydown', event => { if (event.key === 'Escape') { toggle(indexPanel, false); toggle(notesPanel, false); } if (['ArrowRight', 'PageDown', ' '].includes(event.key)) { event.preventDefault(); goTo(current + 1); } if (['ArrowLeft', 'PageUp'].includes(event.key)) { event.preventDefault(); goTo(current - 1); } if (event.key === 'Home') { event.preventDefault(); goTo(0); } if (event.key === 'End') { event.preventDefault(); goTo(slides.length - 1); } if (event.key.toLowerCase() === 'n') toggle(notesPanel); if (event.key.toLowerCase() === 'i') toggle(indexPanel); });
window.addEventListener('hashchange', () => { const match = location.hash.match(/slide-(\d+)/); if (match) goTo(Number(match[1]) - 1); });
const initial = location.hash.match(/slide-(\d+)/); if (initial) current = Number(initial[1]) - 1;
if (printAll) renderAllForPrint(); else render();
